local textures,observed={},{}
local white,transparent={255,255,255,255},{255,255,255,0}
local roles={'text','muted','green','unbeaten','row'}
local plans,plan_count={},0
local queue=nil
local function layout(s)
 local cached=plans[s];if cached then return cached end
 local plan={width=0}
 for _,code in utf8.codes(s)do
  local n=glyphs[code] or glyphs[63]
  plan[#plan+1]={offset=plan.width,source={n%32*32,math.floor(n/32)*32,32,32}}
  plan.width=plan.width+(advances[code] or 24)
 end
 if plan_count>=512 then plans={};plan_count=0 end
 plans[s]=plan;plan_count=plan_count+1;return plan
end
function M.measure(s)return layout(s).width end
function M.advance(code)return advances[code] or 24 end
local function render(g,cmd)
 for _,glyph in ipairs(cmd.plan)do
  g.image(cmd.tex,cmd.x+(glyph.offset-1)*cmd.scale,cmd.y,32*cmd.scale,32*cmd.scale,white,glyph.source)
 end
end
function M.begin_frame()queue={}end
function M.flush(g)
 local commands=queue;queue=nil
 for _,cmd in ipairs(commands or {})do render(g,cmd)end
end
function M.load(g)
 if not g.load_image or (g.image_api_version or 0)<2 then return end
 for _,theme in ipairs({'day','night'})do for _,role in ipairs(roles)do
  local key=theme..'_'..role
  if key~='day_row' then textures[key]=g.load_image('lib/ui/font_'..key..'.png')end
 end end
 textures.day_row=textures.day_text
end
function M.prepare(g,theme)
 local visited={};local changed=false
 for _,role in ipairs(roles)do
  local key=theme..'_'..role;local tex=textures[key]
  if tex and not visited[tex] then
   visited[tex]=true
   local state=g.image_status and g.image_status(tex) or 'ready'
   if observed[key]~=state then
    observed[key]=state;changed=true
    if mod.info then mod.info('[BossChecklist Font] v1.0.11 '..key..' '..state)end
   end
   if state=='pending' then g.image(tex,0,0,1,1,transparent,{0,0,1,1})end
  end
 end
 if changed and mod.write_file then
  local lines={};for k,v in pairs(observed)do lines[#lines+1]=k..' '..v end
  table.sort(lines);mod.write_file('bosschecklist_font.log','v1.0.11 glyph renderer\n'..table.concat(lines,'\n'))
 end
end
function M.draw(g,theme,palette,x,y,s,color,scale)
 if s=='' then return true end
 local role='text';for _,k in ipairs(roles)do if color==palette[k]then role=k;break end end
 local tex=textures[theme..'_'..role]
 if not tex or (g.image_status and g.image_status(tex)~='ready')then return false end
 local cmd={tex=tex,x=x,y=y,scale=scale,plan=layout(s)}
 if queue then queue[#queue+1]=cmd else render(g,cmd)end
 return true
end
return M
